package com.crh.logon.webservices.clients.beans.pricingcall;

import java.io.Serializable;
import java.util.Date;

/**
 * @author AdNovum Informatik AG
 * 
 * Data Transfer Object from business tier to the webservice client 
 * tier. This object will be created and filled in the business tier, and 
 * converted/read in the webservices-client tier into the data model for SAP
 * as generated by AXIS.
 * 
 * Represents: ZFSD_PRICE_SIMULATION / {@code ZSSD_PS_HEADER} 
 */
public class PricingCallDTOHeader implements Serializable {

	private static final long serialVersionUID = 3426002065960581677L;
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZSSD_PS_HEADER / SALES_ORG
	 */
	private String salesOrg;
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZSSD_PS_HEADER / DISTR_CHAN
	 */	
	private String distributionChannel;
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZSSD_PS_HEADER / DIVISION
	 */	
	private String division;
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZSSD_PS_HEADER / SALES_OFF
	 */	
	private String salesOffice;
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZSSD_PS_HEADER / CUST_GROUP
	 */	
	private String customerGroup;
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZSSD_PS_HEADER / ORD_REASON
	 */	
	private String orderReason;
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZSSD_PS_HEADER / PRICE_DATE
	 */	
	private Date priceDate;
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZSSD_PS_HEADER / SHIP_COND
	 */	
	private String shippingConditions;
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZSSD_PS_HEADER / CURRENCY 
	 */	
	private String currency;

	public String getSalesOrg() {
		return salesOrg;
	}

	public void setSalesOrg(String salesOrg) {
		this.salesOrg = salesOrg;
	}

	public String getDistributionChannel() {
		return distributionChannel;
	}

	public void setDistributionChannel(String distributionChannel) {
		this.distributionChannel = distributionChannel;
	}

	public String getDivision() {
		return division;
	}

	public void setDivision(String division) {
		this.division = division;
	}

	public String getSalesOffice() {
		return salesOffice;
	}

	public void setSalesOffice(String salesOffice) {
		this.salesOffice = salesOffice;
	}

	public String getCustomerGroup() {
		return customerGroup;
	}

	public void setCustomerGroup(String customerGroup) {
		this.customerGroup = customerGroup;
	}

	public String getOrderReason() {
		return orderReason;
	}

	public void setOrderReason(String orderReason) {
		this.orderReason = orderReason;
	}

	public Date getPriceDate() {
		return priceDate;
	}

	public void setPriceDate(Date priceDate) {
		this.priceDate = priceDate;
	}

	public String getShippingConditions() {
		return shippingConditions;
	}

	public void setShippingConditions(String shippingConditions) {
		this.shippingConditions = shippingConditions;
	}

	public String getCurrency() {
		return currency;
	}

	public void setCurrency(String currency) {
		this.currency = currency;
	}

	@Override
	public String toString() {
		return "PricingCallDTOHeader [salesOrg=" + salesOrg + ", distributionChannel="
				+ distributionChannel + ", division=" + division + ", salesOffice=" + salesOffice
				+ ", customerGroup=" + customerGroup + ", orderReason=" + orderReason
				+ ", priceDate=" + priceDate + ", shippingConditions=" + shippingConditions
				+ ", currency=" + currency + "]";
	}
	
}
